function formatName(str){if(!str)return"";const lower=str.toLowerCase().trim();if(lower==="sdl"||lower==="sdls")return"SDL";if(lower==="aetcom")return"AETCOM";if(lower==="ece")return"ECE";if(lower==="assignments"||lower==="assignment")return"Assignments";if(lower==="practicals"||lower==="practical")return"Practicals";if(lower==="notes"||lower==="note")return"Notes";if(lower==="homework")return"Homework";if(lower==="project"||lower==="projects")return"Project";if(lower==="other"||lower==="others")return"Other Resources";if(lower==="community_medicine"||lower==="community medicine"||lower==="community")return"Community Medicine";return str.replace(/[_\-]+/g," ").replace(/\b\w/g,char=>char.toUpperCase());}
