function updateStatsCounters(){const total=MBBS_RESOURCES.length;const anatCount=MBBS_RESOURCES.filter(r=>r.subject==="anatomy").length;const physCount=MBBS_RESOURCES.filter(r=>r.subject==="physiology").length;const biocCount=MBBS_RESOURCES.filter(r=>r.subject==="biochemistry").length;if(DOM.statTotal)DOM.statTotal.textContent=total;if(DOM.statAnatomy)DOM.statAnatomy.textContent=anatCount;if(DOM.statPhysiology)DOM.statPhysiology.textContent=physCount;if(DOM.statBiochem)DOM.statBiochem.textContent=biocCount;}
